local ARROW = " = "
local SHOW_LEGEND = false

local function xml_escape(s)
  s = tostring(s or "")
  s = s:gsub("&","&amp;"):gsub("<","&lt;"):gsub(">","&gt;"):gsub('"',"&quot;")
  return s
end

local function is_identity(rec)
  if not rec or not rec.ingredients or #rec.ingredients ~= 1 then return false end
  local ing = rec.ingredients[1]
  return (string.lower(rec.result_name or "") == string.lower(ing.name or "")) and
         (tostring(rec.result_type or "") == tostring(ing.type or "")) and
         ((rec.result_amount or 0) == (ing.amount or 0))
end

local function tag_wrap(tag, s)
  tag = tostring(tag or ""):gsub("[^%w_]", "")
  return "<"..tag..">"..tostring(s).."<>"
end

-- forceCommodity=true for Cooking so all inputs render yellow like Substances
local function wiki_line(rec, forceCommodity)
  local function resultName(n) return "<TECHNOLOGY>"..xml_escape(n).."<>" end
  local function ingName(n, t)
    local tag = "COMMODITY"
    return "<"..tag..">"..xml_escape(n).."<>"
  end
  local function typeTag(t)
    if not SHOW_LEGEND then return "" end
    return (t == "Substance") and " [S]" or " [P]"
  end

  local left  = string.format("%s x%d%s", resultName(rec.result_name), rec.result_amount, typeTag(rec.result_type))

  local parts = {}
  for i=1,#rec.ingredients do
    local ing = rec.ingredients[i]
    parts[#parts+1] = string.format("%s%s x%d", ingName(ing.name, ing.type), typeTag(ing.type), ing.amount)
  end

  return left .. ARROW .. table.concat(parts, " + ")
end

local function ingredients_key(rec)
  local names = {}
  for i=1,#rec.ingredients do
    names[#names+1] = string.lower(rec.ingredients[i].name or "")
  end
  table.sort(names)
  return table.concat(names, " + ")
end

local function build_body_text(recipes, forceCommodity)
  local list = {}
  for i=1,#recipes do
    local r = recipes[i]
    if r and r.result_name and r.ingredients and #r.ingredients > 0 and not is_identity(r) then
      list[#list+1] = r
    end
  end
  table.sort(list, function(a,b)
    local ra, rb = string.lower(a.result_name or ""), string.lower(b.result_name or "")
    if ra == rb then
      return ingredients_key(a) < ingredients_key(b)
    else
      return ra < rb
    end
  end)
  local lines, prevNameLower = {}, nil
  for i=1,#list do
    local r = list[i]
    local nameLower = string.lower(r.result_name or "")
    if prevNameLower and nameLower ~= prevNameLower then
      lines[#lines+1] = ""
    end
    lines[#lines+1] = wiki_line(r, forceCommodity)
    prevNameLower = nameLower
  end
  return table.concat(lines, "\n")
end

