local function make_loc_entry(id, texts_by_field)
  local b = {}
  b[#b+1] = '    <Property value="TkLocalisationEntry.xml">'
  b[#b+1] = ('      <Property name="Id" value="%s" />'):format(id)
  for _,field in ipairs(LANG_ORDER) do
    local val = texts_by_field[field] or texts_by_field["English"] or ""
    val = val:gsub("\n", "&#xA;")
    val = xml_escape(val):gsub("&amp;#xA;", "&#xA;")
    val = val:gsub("%%","%%%%")
    b[#b+1] = ('      <Property name="%s" value="%s" />'):format(field, val)
  end
  b[#b+1] = '    </Property>'
  return table.concat(b, "\n")
end

local CAT_REF_ID        = "UI_HC_REFINER_CAT"
