local entries_xml = table.concat(LOC_ENTRIES, "\n")
local LOC_TABLE_EXML =
  '<?xml version="1.0" encoding="utf-8"?>\n' ..
  '<Data template="cTkLocalisationTable">\n' ..
  '  <Property name="Table">\n' ..
  entries_xml .. '\n' ..
  '  </Property>\n' ..
  '</Data>'

local function topic_xml(topic_id, short_id, page_id, icon_fname, notify_fname)
  local t = {}
  t[#t+1] = '      <Property name="Topics" value="GcWikiTopic.xml">'
  t[#t+1] = ('        <Property name="TopicID" value="%s" />'):format(topic_id)
  t[#t+1] = ('        <Property name="ShortDescriptionID" value="%s" />'):format(short_id)
  t[#t+1] = '        <Property name="Icon" value="TkTextureResource.xml">'
  t[#t+1] = ('          <Property name="Filename" value="%s" />'):format(icon_fname)
  t[#t+1] = '        </Property>'
  t[#t+1] = '        <Property name="NotifyIcon" value="TkTextureResource.xml">'
  t[#t+1] = ('          <Property name="Filename" value="%s" />'):format(notify_fname)
  t[#t+1] = '        </Property>'
  t[#t+1] = '        <Property name="Pages">'
  t[#t+1] = '          <Property name="Pages" value="GcWikiPage.xml">'
  t[#t+1] = ('            <Property name="PageID" value="%s" />'):format(page_id)
  t[#t+1] = '            <Property name="Icon" value="TkTextureResource.xml">'
  t[#t+1] = ('              <Property name="Filename" value="%s" />'):format(icon_fname)
  t[#t+1] = '            </Property>'
  t[#t+1] = ('            <Property name="Content" value="%s_BODY" />'):format(page_id)
  t[#t+1] = '            <Property name="VRContent" value="" />'
  t[#t+1] = '            <Property name="VRAnyHandControlContent" value="" />'
  t[#t+1] = '            <Property name="VRMoveControllerContent" value="" />'
  t[#t+1] = '            <Property name="ContentImage" value="TkTextureResource.xml">'
  t[#t+1] = '              <Property name="Filename" value="" />'
  t[#t+1] = '            </Property>'
  t[#t+1] = '          </Property>'
  t[#t+1] = '        </Property>'
  t[#t+1] = '        <Property name="Mission" value="" />'
  t[#t+1] = '        <Property name="MissionButtonText" value="UI_GUIDE_START_MISSION" />'
  t[#t+1] = '        <Property name="Seen" value="false" />'
  t[#t+1] = '        <Property name="Unlocked" value="true" />'
  t[#t+1] = '        <Property name="ActionSet" value="GcActionSetType.xml">'
  t[#t+1] = '          <Property name="ActionSetType" value="OnFootControls" />'
  t[#t+1] = '        </Property>'
  t[#t+1] = '      </Property>'
  return table.concat(t, "\n")
end

local function build_category_xml(cat_id, cat_upper, topics, isCook)
  local icon_on  = isCook and "TEXTURES/UI/FRONTEND/ICONS/WIKI/WIKI.COOKING.ON.DDS" or "TEXTURES/UI/FRONTEND/ICONS/WIKI/WIKI.RAWMAT.ON.DDS"
  local icon_off = isCook and "TEXTURES/UI/FRONTEND/ICONS/WIKI/WIKI.COOKING.OFF.DDS" or "TEXTURES/UI/FRONTEND/ICONS/WIKI/WIKI.RAWMAT.OFF.DDS"
  local notify_c = isCook and "TEXTURES/UI/HUD/ICONS/WIKI/SURVIVAL7.DDS"    or "TEXTURES/UI/HUD/ICONS/WIKI/TRADE6.DDS"
  local cat = {}
  cat[#cat+1] = '  <Property value="GcWikiCategory.xml">'
  cat[#cat+1] = ('    <Property name="CategoryID" value="%s" />'):format(cat_id)
  cat[#cat+1] = ('    <Property name="CategoryIDUpper" value="%s" />'):format(cat_upper)
  cat[#cat+1] = ('    <Property name="IconOn" value="TkTextureResource.xml"><Property name="Filename" value="%s" /></Property>'):format(icon_on)
  cat[#cat+1] = ('    <Property name="IconOff" value="TkTextureResource.xml"><Property name="Filename" value="%s" /></Property>'):format(icon_off)
  cat[#cat+1] = '    <Property name="Topics">'
  for _,tp in ipairs(topics) do
    cat[#cat+1] = topic_xml(tp.topic_id, tp.short_id, tp.page, icon_on, notify_c)
  end
  cat[#cat+1] = '    </Property>'
  cat[#cat+1] = '    <Property name="Type" value="GcWikiTopicType.xml"><Property name="WikiTopicType" value="Guide" /></Property>'
  cat[#cat+1] = '    <Property name="Items" />'
  cat[#cat+1] = '    <Property name="UnseenCount" value="0" />'
  cat[#cat+1] = '    <Property name="UnlockedCount" value="0" />'
  cat[#cat+1] = '  </Property>'
  return table.concat(cat, "\n")
end

